function assertNever(x: never): never {
  throw new Error('Unexpected: ' + JSON.stringify(x));
}

function handle(r: Result) {
  switch (r.status) {
    case 'ok': return r.data;
    case 'err': return r.message;
    default: return assertNever(r);
  }
